let case name = List.find (fun value -> Json.string (get "name" value) = name) fixtures
let authorities name = let fixture = case name in Registry.of_json (get "registry" fixture), R.of_json (get "request" fixture)
let () =
  require (List.length fixtures = 15) "Independent selection fixture census changed";
  List.iter (fun fixture ->
    let name = Json.string (get "name" fixture) in
    let registry = Registry.of_json (get "registry" fixture) and request = R.of_json (get "request" fixture) in
    let expected = Result.of_json (get "result" fixture) in
    let result = Producer.select ~registry ~request () in
    require (Registry.fingerprint registry = Json.string (get "registry_fingerprint" fixture)) (name ^ ": registry identity differs");
    require (R.fingerprint request = Json.string (get "request_fingerprint" fixture)) (name ^ ": request identity differs");
    require (Result.fingerprint result = Json.string (get "result_fingerprint" fixture)) (name ^ ": full result identity differs");
    require (Canonical.encode (Result.to_json result) = Canonical.encode (get "result" fixture)) (name ^ ": complete result content differs");
    require (Result.outcome_name (Result.outcome result) = Json.string (get "outcome" fixture)) (name ^ ": outcome differs");
    require (Producer.verify_selection ~registry ~request expected) (name ^ ": fresh replay rejected original complete result")) fixtures;
  let registry,request = authorities "baseline" in
  let result,usage = Producer.select_with_usage ~registry ~request () in
  require (usage.components = 3 && usage.work > 0 && usage.input_bytes > 0 && usage.output_bytes > 0)
    "Selection did not account for all three alternatives";
  let changed_request = R.of_json (set "implementation_role" (str "different") (R.to_json request)) in
  require (not (Producer.verify_selection ~registry ~request:changed_request result)) "Saved result accepted changed hard authority";
  let forged = Result.of_json (set "request_fingerprint" (str (R.fingerprint changed_request)) (Result.to_json result)) in
  require (not (Producer.verify_selection ~registry ~request:changed_request forged)) "Rehashed stale selection escaped full replay";
  let altered_alternative = Result.to_json result |> get "alternatives" |> Json.array |> List.map (fun value ->
    if Json.string (get "component_id" value) = "good" then set "reasons" (arr [str "invented eligibility rationale"]) value else value) in
  let forged = Result.of_json (set "alternatives" (arr altered_alternative) (Result.to_json result)) in
  require (not (Producer.verify_selection ~registry ~request forged)) "Selected pin hid altered alternative rationale";
  let selected = Option.get (Result.selected result) |> Registry.Component_lock.to_json |> set "node_id" (str "different_instance") in
  let forged = Result.of_json (set "selected" selected (Result.to_json result)) in
  require (not (Producer.verify_selection ~registry ~request forged)) "Selected component pin hid the wrong instance identity";
  let changed_registry = Registry.to_json registry |> fun raw ->
    let components = Json.array (get "components" raw) |> List.map (fun value ->
      if Json.string (get "id" value) = "unknown" then set "assumptions" (arr [str "changed unselected member"]) value else value) in
    Registry.of_json (set "components" (arr components) raw) in
  require (not (Producer.verify_selection ~registry:changed_registry ~request result)) "Unselected registry member disappeared from authority";
  let raw_request = R.to_json request in
  let arbitrary = R.of_json (set "classification" (str "future classification") raw_request) in
  require (R.classification arbitrary = Some "future classification") "Codec narrowed the historical string classification constraint";
  rejected "component_selection" (fun () -> R.of_json (set "component_version" (str "2") raw_request));
  rejected "component_selection" (fun () -> R.of_json (set "preferred_component_ids" (arr [str "a";str "a"]) raw_request));
  rejected "component_selection" (fun () -> R.of_json (set "required_guarantees" (arr [str "a";str "a"]) raw_request));
  let pin = Pinned_identity.make ~kind:Pinned_identity.Model ~id:"model" ~version:"1" ~content_fingerprint:(String.make 64 'a') in
  let duplicate = R.make ~implementation_role:(R.implementation_role request) ~target:(R.target request)
    ~required_domain:(R.required_domain request) ~required_identities:[pin;pin] () in
  require (List.length (R.required_identities duplicate) = 1) "Equal complete pins were not deduplicated";
  let changed_pin = Pinned_identity.make ~kind:Pinned_identity.Model ~id:"model" ~version:"1" ~content_fingerprint:(String.make 64 'b') in
  rejected "component_selection" (fun () -> R.make ~implementation_role:(R.implementation_role request) ~target:(R.target request)
    ~required_domain:(R.required_domain request) ~required_identities:[pin;changed_pin] ());
  let alt = List.hd (Result.alternatives result) in
  rejected "component_selection" (fun () -> A.of_json (set "reasons" (arr []) (A.to_json alt)));
  rejected "component_selection" (fun () -> A.of_json (set "preference_rank" (Json.int (-1)) (A.to_json alt)));
  rejected "invalid_type" (fun () -> A.of_json (set "preference_rank" (Json.Bool true) (A.to_json alt)));
  let enormous_rank = Z.pow (Z.of_int 10) 100 in
  let rank = A.make ~component_id:"huge" ~version:"1" ~content_fingerprint:(String.make 64 'a')
    ~status:A.Eligible ~reasons:["explicit"] ~preference_rank:enormous_rank () in
  require (A.preference_rank (A.of_json (A.to_json rank)) = Some enormous_rank) "Historical arbitrary integer preference rank narrowed";
  rejected "component_selection" (fun () -> Result.of_json (set "selected" Json.Null (Result.to_json result)));
  rejected "component_selection" (fun () -> Result.of_json (set "alternatives" (arr [A.to_json alt;A.to_json alt]) (Result.to_json result)));
  let human_result = Result.of_json (get "result" (case "human")) in
  rejected "component_selection" (fun () -> Result.of_json (set "admission" (Admission.Assessment.to_json (Result.admission human_result)) (Result.to_json result)));
  List.iter (fun (code,change) -> rejected code (fun () -> R.of_json (change raw_request)))
    ["missing_field",(fun raw -> Json.Object (List.remove_assoc "target" (Json.object_fields raw)));
     "unknown_field",set "extra" Json.Null;"unsupported_schema",set "schema_version" (str "future");
     "invalid_name",set "implementation_role" (str " ");"invalid_type",set "implementation_role" Json.Null];
  let rec cyclic = Json.Array [cyclic] in
  rejected "component_selection_cycle" (fun () -> S.measure cyclic);
  let rec cyclic_names = "name" :: cyclic_names in
  rejected "component_selection_limit" (fun () -> R.make ~implementation_role:"sensor" ~target:(R.target request)
    ~required_domain:(R.required_domain request) ~preferred_component_ids:cyclic_names ());
  let unicode = Json.Object ["é😀",Json.Array [Json.Float (-0.);Json.Int enormous_rank;str "\n\t\000"]] in
  let bytes,nodes = S.measure unicode in
  require (bytes = String.length (Canonical.encode unicode) && nodes = 6) "Exact UTF-8 byte/key-value count differs";
  let parent = W.create ~profile:"literal.selection" ~error_code:"literal_custom_selection" ~maximum:50_000_000 () in
  let same,nested = Producer.select_with_usage ~parent ~registry ~request () in
  require (Result.fingerprint same = Result.fingerprint result && W.remaining parent = 50_000_000 - nested.work)
    "Selection escaped caller shared work";
  let tiny_parent = W.create ~profile:"literal.selection" ~error_code:"literal_custom_selection" ~maximum:1 () in
  rejected "literal_custom_selection" (fun () -> Producer.select ~parent:tiny_parent ~registry ~request ());
  List.iter (fun (code,limits) -> rejected code (fun () -> Producer.select ~limits ~registry ~request ()))
    ["component_selection_work_limit",Producer.make_limits ~max_work:1 ();
     "component_selection_search_limit",Producer.make_limits ~max_components:2 ();
     "component_selection_input_limit",Producer.make_limits ~max_input_bytes:1 ();
     "component_selection_output_limit",Producer.make_limits ~max_output_bytes:1 ();
     "component_selection_output_limit",Producer.make_limits ~max_output_nodes:1 ()];
  List.iter (fun limits -> require (Result.fingerprint (Producer.select ~limits ~registry ~request ()) = Result.fingerprint result)
    "Exact recorded selection boundary rejected its result")
    [Producer.make_limits ~max_work:usage.work ();Producer.make_limits ~max_components:usage.components ();
     Producer.make_limits ~max_input_bytes:usage.input_bytes ();Producer.make_limits ~max_output_bytes:usage.output_bytes ()];
  List.iter (fun (code,limits) -> rejected code (fun () -> Producer.select ~limits ~registry ~request ()))
    ["component_selection_work_limit",Producer.make_limits ~max_work:(usage.work-1) ();
     "component_selection_input_limit",Producer.make_limits ~max_input_bytes:(usage.input_bytes-1) ();
     "component_selection_output_limit",Producer.make_limits ~max_output_bytes:(usage.output_bytes-1) ()];
  let replay_parent = W.create ~profile:"literal.replay" ~error_code:"literal_replay_limit" ~maximum:50_000_000 () in
  let replay,replay_usage = Producer.verify_selection_with_usage ~parent:replay_parent ~registry ~request result in
  require (replay && W.remaining replay_parent = 50_000_000-replay_usage.work && replay_usage.work > usage.work)
    "Fresh report replay omitted supplied report or recomputation work";
  (* Publication32MiB and input16MiB are intentionally separate ceilings. *)
  let reason = String.make 3_500_000 'x' in
  let large = List.init 5 (fun index -> A.make ~component_id:(string_of_int index) ~version:"1"
    ~content_fingerprint:(String.make 64 'a') ~status:A.Rejected ~reasons:[reason] ()) in
  let large = Result.make ~registry_fingerprint:(Registry.fingerprint registry) ~request_fingerprint:(R.fingerprint request)
    ~selected:None ~alternatives:large ~admission:(Result.admission result) in
  require (Result.canonical_size large > Limits.max_request_bytes && Result.canonical_size large < Limits.max_response_bytes)
    "Publication result did not retain the explicit larger response ceiling";
  rejected "component_selection_limit" (fun () -> Result.of_json (Result.to_json large));
  print_endline "component selection:15 full independent result literals, all hard constraints/ranks/admission, fresh replay, strict codecs and cumulative shared bounds checked"
